contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint waitTime) public payable {
        // c starts fresh at deployment; pastBlockTime is 0 at first call.
        uint beforePast = c.pastBlockTime();
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        require(address(this).balance >= amount);

        bool reverted;
        if (amount != 10 ether) {
            // Any value other than exactly 10 ether must revert.
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(reverted == true);
            return;
        }

        // amount == 10 ether: outcome depends on timestamp guard.
        // If timestamp is not strictly greater, it must revert; otherwise complete.
        // We cannot compare to block.timestamp exactly, but we can observe that
        // a successful call updates pastBlockTime to a strictly larger value.
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        if (reverted) {
            // Revert and state/ether unchanged.
            assert(afterPast == beforePast);
            assert(afterC == beforeC);
            assert(afterSelf == beforeSelf);
        } else {
            // Success: pastBlockTime moved forward, c received the ether,
            // and the caller lost exactly that ether (unless c refunded on block.number%15).
            assert(afterPast > beforePast);
            assert(afterC >= beforeC);
            assert(afterC - beforeC + (beforeSelf - afterSelf) == amount || afterC == beforeC);
        }
    }

    receive() external payable {}
}

