contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 timestamp) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTime = c.pastBlockTime();
        require(timestamp > beforeTime, "timestamp must exceed pastBlockTime");

        // Make the block timestamp strictly greater than the stored pastBlockTime,
        // but not equal in case the stored value is especially large.
        if (timestamp <= block.timestamp) {
            timestamp = block.timestamp + 1;
        }
        // Ensure the timestamp stays within a range that still gives a valid precondition
        // after potential adjustment. If not, the require above would have already failed.
        require(timestamp > beforeTime, "adjusted timestamp must exceed pastBlockTime");

        uint256 cBalBefore = address(c).balance;
        uint256 thisBalBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();
        uint256 cBalAfter = address(c).balance;
        uint256 thisBalAfter = address(this).balance;

        // General rule: a fallback call sending exactly 10 ether must succeed when the
        // timestamp is strictly greater than pastBlockTime, must set pastBlockTime to the
        // current timestamp, must increase c's balance by exactly the amount, and must not
        // decrease this contract's balance by more than the amount (the remainder may be
        // refunded by the payout branch).
        assert(
            !reverted &&
            afterTime == timestamp &&
            cBalAfter == cBalBefore + amount &&
            thisBalBefore >= thisBalAfter &&
            (thisBalBefore - thisBalAfter) <= amount
        );
    }

    receive() external payable {}
}

