contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 ts, uint256 amount) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(ts > block.timestamp, "ts must be strictly greater than current block timestamp");
        require(address(this).balance >= amount, "insufficient balance");

        // Ensure the stored timestamp is older than ts, so the call can succeed.
        // First call with a timestamp strictly before ts to set a baseline.
        uint256 firstTs = ts - 1;
        // Use a looping trick? No loops allowed as top-level statements only.
        // Instead, directly require that c.pastBlockTime() is less than ts, but we cannot
        // require on c's state before the call that creates it.  We must set it up.
        //
        // We can call the fallback twice: first with timestamp = ts - 1, then with ts.
        // But we need to ensure the first call succeeds: it requires 10 ether and timestamp > pastBlockTime.
        // Since this is a fresh c, pastBlockTime is initially 0, so any ts > 0 works.
        // However, ts - 1 might be less than current block timestamp? We require ts > block.timestamp,
        // so ts - 1 >= block.timestamp, and pastBlockTime was 0, so the first call with ts - 1 is valid.
        // But careful: the first call uses block.timestamp of the current block, which is the same for both calls.
        // The second call requires block.timestamp > pastBlockTime (which is ts - 1). But block.timestamp is constant
        // within a transaction, so it cannot be > ts - 1 if ts - 1 >= block.timestamp. This is a problem.
        //
        // The contract checks block.timestamp > pastBlockTime, not the argument. So the second call will use the same
        // block.timestamp and require it > (ts - 1) which fails. Thus we cannot make two calls within the same transaction
        // unless the first call set pastBlockTime to something less than block.timestamp.
        // But to set pastBlockTime to less than block.timestamp, we need a successful call with block.timestamp > old
        // pastBlockTime (initially 0). That works: first call with amount 10 ether, then pastBlockTime = block.timestamp.
        // Then second call would require block.timestamp > pastBlockTime, which is false (equal), so it reverts.
        //
        // Therefore, within a single transaction, we can only make one fallback call that successfully changes state.
        // The property must be about a single call from a fresh state.
        //
        // Let's define the property for a single call: if we send exactly 10 ether, the call completes
        // and pastBlockTime becomes block.timestamp.

        uint256 pastBefore = c.pastBlockTime();
        uint256 blockTimestampBefore = block.timestamp;

        // Perform the call that changes state.
        (bool success, ) = address(c).call{value: amount}("");

        // Read after state.
        uint256 pastAfter = c.pastBlockTime();

        // The rule: the call succeeds because block.timestamp > pastBlockTime (which is 0 initially or set by setup?)
        // Since this is a fresh contract, pastBlockTime is 0, and block.timestamp > 0, so the require passes.
        // However, we cannot guarantee pastBefore is 0 because the constructor is empty and no prior calls in this test.
        // The checker deploys a fresh c, so pastBlockTime is 0 before run. But to make the rule general,
        // we should not assume pastBefore == 0; we could have a precondition that we first ensure pastBlockTime < block.timestamp
        // by requiring it? But we cannot require on c's state before the state-changing call.
        //
        // The accepted rule should be: for any input, if the call succeeds, pastBlockTime equals block.timestamp.
        // But we want a rule that holds for all inputs? The task says "a general rule that P satisfies for ALL inputs".
        // But the contract has a require that can revert if msg.value != 10 ether or block.timestamp <= pastBlockTime.
        // So the rule must cover the revert case too.
        //
        // Let's write: if the call reverts, then either amount != 10 ether or block.timestamp <= pastBefore.
        // And if it succeeds, then pastAfter == block.timestamp.
        // That is a general rule that holds for all inputs.

        assert(
            (success && pastAfter == blockTimestampBefore) ||
            (!success && (amount != 10 ether || blockTimestampBefore <= pastBefore))
        );
    }

    receive() external payable {}
}

