    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 pastBlockTimeAfter = c.pastBlockTime();
        bool expectedSuccess = (amount == 10 ether) && (block.timestamp > pastBlockTimeAfter);
        assert(reverted != expectedSuccess);
    }

    receive() external payable {}
}

