contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 value, uint256 timeDelta) public payable {
        require(address(this).balance >= value);
        uint256 beforeTime = c.pastBlockTime();
        uint256 newTime = beforeTime + timeDelta;
        bool reverted;
        (bool ok, ) = address(c).call{value: value}(abi.encodeWithSignature(""));
        reverted = !ok;
        // The pre-state timestamp might be 0, and block.timestamp is always > 0 in practice,
        // so for the success branch we require value == 10 ether and block.timestamp > beforeTime.
        // However, we cannot directly control block.timestamp from here; property models expected behavior.
        // We assert the general invariant: if the call reverted, either value != 10 ether or the timestamp condition failed.
        // If the call succeeded, value must have been 10 ether and the timestamp must have increased.
        // Since block.timestamp is not an input, we approximate by checking the observable effects.
        // The key observable: pastBlockTime only changes on success, and there is no return value.
        // We assert: reverted == (value != 10 ether || block.timestamp <= beforeTime).
        // But block.timestamp is not an input; we cannot know it. However, since the call is in the same transaction,
        // block.timestamp is fixed. The test can only check that value must be 10 ether for success,
        // and that pastBlockTime increases on success.
        // To make a general rule over inputs, we capture the timestamp before the call, then after.
        // The contract sets pastBlockTime = block.timestamp on success.
        // We cannot read block.timestamp directly in the assert except by reading c.pastBlockTime() after.
        // The rule: if the call did not revert, then value == 10 ether and c.pastBlockTime() > beforeTime.
        // If the call reverted, then value != 10 ether or c.pastBlockTime() == beforeTime (timestamp did not advance).
        // Since block.timestamp is monotonic and the contract requires block.timestamp > pastBlockTime,
        // in a fresh state pastBlockTime=0, so any block.timestamp > 0 would allow success with 10 ether.
        // To make the test meaningful, we require a precondition on the input so that the timestamp change is observable.
        // We can expect that for value == 10 ether and a sufficient timeDelta, the call succeeds.
        // But we cannot control block.timestamp. So we write a property that holds regardless: 
        // If the call succeeded, then value == 10 ether and c.pastBlockTime() > beforeTime.
        // If the call reverted and value == 10 ether, then it must be because block.timestamp <= beforeTime.
        // We cannot express block.timestamp, so we assert the simpler consequence: 
        // success implies value == 10 ether and pastBlockTime changed.
        // We will structure the assert to capture this.
        uint256 afterTime = c.pastBlockTime();
        if (reverted) {
            // If reverted, either value != 10 ether OR the timestamp did not increase (i.e., afterTime == beforeTime).
            assert(value != 10 ether || afterTime == beforeTime);
        } else {
            // If success, value must be 10 ether and afterTime must equal block.timestamp (which we don't have) but must be > beforeTime.
            assert(value == 10 ether && afterTime > beforeTime);
        }
    }
    receive() external payable {}
}

