contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint before = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        // General rule:
        // - If amount != 10 ether, the call must revert.
        // - If amount == 10 ether and block.timestamp <= before, the call must revert.
        // - If amount == 10 ether and block.timestamp > before, the call must succeed
        //   and pastBlockTime must become block.timestamp.
        // In all cases, a reverted call must not change pastBlockTime.
        assert(
            (amount != 10 ether && reverted && afterTime == before) ||
            (amount == 10 ether && (block.timestamp <= before ? (reverted && afterTime == before)
                                                              : (!reverted && afterTime == block.timestamp)))
        );
    }

    receive() external payable {}
}

