contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");
        require(block.timestamp > c.pastBlockTime(), "timestamp must be strictly increasing");

        uint balBefore = address(c).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == balBefore + amount);
            }
        }
    }

    receive() external payable {}
}

