contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether || amount != 10 ether, "unreachable");

        uint beforeTs = c.pastBlockTime();
        require(address(this).balance >= amount, "insufficient balance");
        bool reverted;
        if (amount == 10 ether) {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.fallback{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (amount == 10 ether) {
            assert(!reverted);
            assert(c.pastBlockTime() > beforeTs || c.pastBlockTime() == block.timestamp);
        } else {
            assert(reverted);
            assert(c.pastBlockTime() == beforeTs);
        }
    }

    receive() external payable {}
}

