    function run(uint prepAmount, uint amount) public payable {
        require(prepAmount == 10 ether);
        require(amount == 10 ether);
        require(address(this).balance >= prepAmount + amount, "not enough balance");

        // Establish prior state so pastBlockTime is nonzero.
        (bool prepSuccess, ) = address(c).call{value: prepAmount}("");
        uint before = c.pastBlockTime();
        require(prepSuccess && before != 0, "prep failed");

        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        if (!success) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterVal = c.pastBlockTime();
        if (reverted) {
            assert(afterVal == before);
        } else {
            assert(afterVal == block.timestamp && afterVal > before);
        }
    }

    receive() external payable {}
}

