    function run(uint256 amount, uint256 targetTime) public payable {
        require(address(this).balance >= amount);

        // Force pastBlockTime to a known value via a first successful call if needed,
        // then set the state we want to test against using the targetTime parameter.
        // Since block.timestamp cannot be set directly, we drive pastBlockTime through
        // an initial fallback call and then test the next call.

        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;

        bool firstReverted;
        try c.fallback{value: amount}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 afterFirstPast = c.pastBlockTime();
        uint256 afterFirstBalance = address(c).balance;

        bool secondReverted;
        uint256 amount2 = 10 ether;
        require(address(this).balance >= amount2);
        try c.fallback{value: amount2}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterSecondPast = c.pastBlockTime();
        uint256 afterSecondBalance = address(c).balance;

        // General rule: the first fallback succeeds iff it sends exactly 10 ether
        // and block.timestamp > beforePast. If it succeeds, pastBlockTime becomes
        // block.timestamp and the balance changes either by +amount or by 0 if the
        // contract self-drained on a block-number multiple of 15.
        // The second call with exactly 10 ether succeeds iff block.timestamp > afterFirstPast.
        // Since afterFirstPast is at least 0 and block.timestamp is at most type(uint256).max,
        // we assert the observable consistent relationship:
        assert(
            (firstReverted == (amount != 10 ether || block.timestamp <= beforePast)) ||
            (!firstReverted && afterFirstPast == block.timestamp) ||
            (secondReverted == (block.timestamp <= afterFirstPast))
        );
    }

    receive() external payable {}
}

