    constructor(C _c) { c = _c; }

    function run(uint256 tooEarly, uint256 tooLate) public payable {
        // Parameter 1: tooEarly is a timestamp not greater than the current pastBlockTime,
        // expressed as an offset from it (so tooEarly <= c.pastBlockTime()).
        // Parameter 2: tooLate is a timestamp strictly greater than pastBlockTime.
        require(address(this).balance >= 20 ether);

        uint256 beforePast = c.pastBlockTime();

        // Compute an input timestamp that is NOT greater than pastBlockTime.
        // If pastBlockTime() == 0, a value equal to it (0) is used.
        uint256 badTime = beforePast > 0 ? beforePast - (tooEarly % beforePast) : 0;
        // Compute an input timestamp strictly greater than pastBlockTime.
        uint256 goodTime = beforePast + 1 + tooLate;

        // First call: must revert because the provided timestamp is not greater than
        // the stored pastBlockTime.
        c.pastBlockTime();
        bool firstReverted = false;
        uint256 firstBlock = block.number;
        try c.fallback{value: 10 ether}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // The state after the first call must be unchanged: the timestamp was not
        // greater than pastBlockTime, so the call had to revert and no effects
        // should have been applied.
        uint256 midPast = c.pastBlockTime();
        uint256 midBalance = address(c).balance;

        // Second call: must succeed because the provided timestamp is strictly
        // greater than pastBlockTime.
        uint256 secondBlock = block.number;
        bool secondReverted = false;
        try c.fallback{value: 10 ether}() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalance = address(c).balance;

        // General rule: the first call with a timestamp <= pastBlockTime reverts and
        // leaves the stored timestamp and contract balance unchanged; the second call
        // with a timestamp > pastBlockTime must not revert, advances pastBlockTime,
        // and if the block number is divisible by 15 the contract's whole balance is
        // sent to the caller.
        assert(
            firstReverted &&
            midPast == beforePast &&
            midBalance == 20 ether &&
            !secondReverted &&
            afterPast == block.timestamp &&
            afterPast > midPast &&
            (
                (secondBlock % 15 == 0 && afterBalance == 0) ||
                (secondBlock % 15 != 0 && afterBalance == 20 ether)
            )
        );
    }

    receive() external payable {}
}

