contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 delay) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "test contract lacks ether");

        // Read the old value through the public getter.
        uint oldTime = c.pastBlockTime();

        // We can only shape the precondition through block.timestamp indirectly.
        // If oldTime is far in the future, the call below should revert.
        // If it is not, the call should succeed and update the timestamp.
        // We do both branches without nesting calls: one bounded call, then decide.
        uint targetTime = oldTime + uint(delay);

        // Make the deciding fallback call. We cannot control block.timestamp directly,
        // so we run it once and check the postcondition.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            // If the call reverted, then the timestamp must NOT have been greater than oldTime.
            assert(block.timestamp <= oldTime);
            // And pastBlockTime must not have changed.
            assert(c.pastBlockTime() == oldTime);
        } else {
            // If the call completed, then the timestamp must have been greater than oldTime.
            assert(block.timestamp > oldTime);
            // And pastBlockTime must now equal this block's timestamp.
            assert(c.pastBlockTime() == block.timestamp);
        }
    }

    receive() external payable {}
}

