        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 beforeTime = c.pastBlockTime();
        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;
        uint256 afterTime = c.pastBlockTime();

        if (amount != 10 ether) {
            assert(reverted && afterTime == beforeTime);
        } else if (beforeTime >= block.timestamp) {
            assert(reverted && afterTime == beforeTime);
        } else {
            assert(!reverted && afterTime == block.timestamp && afterTime > beforeTime);
        }
    }

    receive() external payable {}
}
